  const lineNo = i + 1
  const record = lines[i]
  try {
    if (mode === 'normalize') {
      outputs.push(normalize(record))
    } else {
      const spaceIdx = record.indexOf(' ')
      if (spaceIdx === -1) throw new NoSpaceError()
      const baseStr = record.slice(0, spaceIdx)
      const refStr = record.slice(spaceIdx + 1)
      outputs.push(resolve(baseStr, refStr))
    }
