    let message
    if (e instanceof NoSpaceError) message = 'expected a base and a reference'
    else if (e instanceof NoBaseSchemeError) message = 'the base has no scheme'
    else if (e instanceof PercentEncodingError) message = e.message
    else throw e
    process.stderr.write(`error: line ${lineNo}: ${message}\n`)
    process.exit(2)
  }
}

process.stdout.write(outputs.map((line) => line + '\n').join(''))
